<?php
declare(strict_types=1);namespace App\Application\Payments;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Models\{Chargeback,PaymentIntentRecord,Refund,User};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class FinancialCaseService{public function __construct(private AuditWriter$audit,private OutboxWriter$outbox){}public function requestRefund(PaymentIntentRecord$i,array$d,User$actor):Refund{if($i->status!=='SUCCEEDED')throw ValidationException::withMessages(['payment'=>__('wave4.refund_requires_success')]);if($e=Refund::where(['tenant_id'=>$i->tenant_id,'idempotency_key'=>$d['idempotency_key']])->first())return$e;$open=Refund::where('payment_intent_id',$i->id)->whereIn('status',['REQUESTED','APPROVED','PROCESSING','COMPLETED'])->sum('amount_minor');if($open+$d['amount_minor']>$i->amount_minor)throw ValidationException::withMessages(['amount_minor'=>__('wave4.refund_exceeds_balance')]);$r=Refund::create([...$d,'tenant_id'=>$i->tenant_id,'payment_intent_id'=>$i->id,'refund_number'=>'RFD-'.strtoupper(Str::random(10)),'currency'=>$i->currency,'status'=>'REQUESTED','requested_by'=>$actor->id]);$this->event('REFUND',$r->id,null,'REQUESTED',$d['reason_code'],$actor);$this->audit->record('refund.requested','refund',$r->id,['amount_minor'=>$r->amount_minor],$r->reason_code);return$r;}public function approveRefund(Refund$r,User$actor):Refund{if($r->status!=='REQUESTED')throw ValidationException::withMessages(['status'=>__('wave4.refund_not_pending')]);if($r->requested_by===$actor->id)throw ValidationException::withMessages(['actor'=>__('wave4.maker_checker')]);$r->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$this->event('REFUND',$r->id,'REQUESTED','APPROVED','APPROVED',$actor);$this->outbox->record('refund.approved','refund',$r->id,['refund_id'=>$r->id]);return$r->refresh();}public function openChargeback(PaymentIntentRecord$i,array$d):Chargeback{return DB::transaction(function()use($i,$d){$c=Chargeback::firstOrCreate(['provider_case_reference'=>$d['provider_case_reference']],[...$d,'tenant_id'=>$i->tenant_id,'payment_intent_id'=>$i->id,'currency'=>$i->currency,'status'=>'OPEN']);$this->event('CHARGEBACK',$c->id,null,'OPEN',$c->reason_code,null);$this->audit->record('chargeback.opened','chargeback',$c->id,['amount_minor'=>$c->amount_minor]);return$c;});}public function resolveChargeback(Chargeback$c,array$d,User$actor):Chargeback{if(!in_array($c->status,['OPEN','UNDER_REVIEW'],true))throw ValidationException::withMessages(['status'=>__('wave4.chargeback_closed')]);$from=$c->status;$c->update(['status'=>$d['decision'],'resolution_notes'=>$d['notes'],'resolved_at'=>now(),'assigned_to'=>$actor->id]);$this->event('CHARGEBACK',$c->id,$from,$d['decision'],$d['reason_code'],$actor);$this->outbox->record('chargeback.resolved','chargeback',$c->id,['chargeback_id'=>$c->id,'decision'=>$d['decision']]);return$c->refresh();}private function event(string$type,string$id,?string$from,string$to,string$reason,?User$actor):void{DB::table('financial_case_events')->insert(['id'=>(string)Str::uuid(),'case_type'=>$type,'case_id'=>$id,'from_status'=>$from,'to_status'=>$to,'reason_code'=>$reason,'actor_id'=>$actor?->id,'metadata'=>'{}','occurred_at'=>now()]);}}
